// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    bytes32 constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(uint256 seed) public {
        vm.assume(seed < type(uint256).max);
        bytes32 slot = c.proxiableUUID();
        assertTrue(slot == IMPLEMENTATION_SLOT, "proxiableUUID must return implementation slot");
    }
}
